struct ValidateIngress: AsyncMiddleware {
    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        if let error = IngressRules.check(request) {
            throw Abort(.badRequest, reason: error)   // rejected
        }
        return try await next.respond(to: request)
    }
}

app.middleware.use(ValidateIngress())
